USE staylocal_update;

-- Keep sample tenant move-in dates visibly distinct for a more useful demo dataset.
UPDATE reservations r JOIN tenants t ON t.id=r.tenant_id SET r.move_in_date=DATE_SUB(CURDATE(),INTERVAL 2 MONTH) WHERE t.email='tenant@staylocal.local' AND r.unit_id=2 AND r.status<>'cancelled';
UPDATE reservations r JOIN tenants t ON t.id=r.tenant_id SET r.move_in_date=DATE_SUB(CURDATE(),INTERVAL 4 MONTH) WHERE t.email='luis@staylocal.local' AND r.unit_id=9 AND r.status<>'cancelled';
UPDATE reservations r JOIN tenants t ON t.id=r.tenant_id SET r.move_in_date=DATE_SUB(CURDATE(),INTERVAL 3 MONTH) WHERE t.email='ana@staylocal.local' AND r.unit_id=18 AND r.status<>'cancelled';
UPDATE reservations r JOIN tenants t ON t.id=r.tenant_id SET r.move_in_date=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) WHERE t.email='rafael@staylocal.local' AND r.unit_id=23 AND r.status<>'cancelled';
-- Safe migration for the existing StayLocal revision. It does not drop tables or application data.
CREATE TABLE IF NOT EXISTS apartment_amenities (apartment_id INT UNSIGNED NOT NULL, amenity ENUM('parking','beach','elevator','pwd_accessible') NOT NULL, PRIMARY KEY(apartment_id,amenity), CONSTRAINT fk_apartment_amenity_apartment FOREIGN KEY(apartment_id) REFERENCES apartments(id) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB;
UPDATE apartments SET policies='• QUIET HOURS — Keep music, calls, and gatherings low from 10:00 PM to 7:00 AM. The tenant is responsible for guests’ conduct.\n• OCCUPANCY & GUESTS — Only occupants listed in the signed lease may reside in the unit. Ask management before adding a long-term occupant; follow front-desk visitor registration.\n• PETS — Prior registration and written approval are required. Use a leash/carrier in shared areas, clean up immediately, and prevent noise or damage.\n• SMOKING — No smoking or vaping inside the unit, corridors, stairwells, or enclosed shared spaces.\n• CORRIDORS & FIRE SAFETY — Keep halls, stairs, landings, and exits clear. Never wedge fire doors or store items in escape routes.\n• WASTE — Bag household rubbish and use the marked collection area and schedule.\n• UTILITIES — Charges use the unit meter or written allocation disclosed by management. Request statements and retain receipts.\n• REPAIRS — Report leaks, electrical faults, pests, and damage promptly; do not attempt electrical or structural repairs.\n• BALCONY & WINDOWS — Secure belongings against wind/rain; do not drain water onto neighboring units.\n• DELIVERIES — Use approved receiving points; do not let strangers follow through secured doors.\n• PARKING — Parking is not included unless written into the lease or separately assigned. Never block ramps, drives, or fire lanes.\n• ALTERATIONS — Obtain written approval before drilling, repainting, changing locks, or installing appliances.\n• MOVE-IN / OUT — Coordinate loading access, record unit condition, and return keys/cards.\n• These are demo rules; verify owner-approved policies, fees, contacts, and signed lease before relying on them.' WHERE id=1 AND policies LIKE 'Quiet hours: 10:00 PM–7:00 AM. Keep corridors and fire exits clear.%';
UPDATE apartments SET policies='• QUIET HOURS — Keep sound low 10:00 PM–7:00 AM.\n• OCCUPANTS — Name residents in the lease and report long-stay guest changes.\n• VISITORS — Follow security sign-in; no access-card sharing.\n• PETS — No pets without prior written approval.\n• PARKING — Use only the written assignment; never use accessible bays without authorization.\n• ELEVATORS — Follow posted capacity; reserve the service lift for moves.\n• ACCESSIBLE ROUTES — Keep ramps, handrails, lobbies, and accessible entrances clear.\n• FIRE & SECURITY — Do not prop doors or store items on stairs; follow evacuation instructions.\n• WASTE — Bag/separate rubbish and use the designated area.\n• UTILITIES — Statements must identify period, allocation/meter basis, amount, and due date.\n• MAINTENANCE — Report urgent water/electrical/safety issues promptly and get approval for contractors.\n• ACCESS — Coordinate non-emergency entry in advance.\n• ALTERATIONS & SMOKING — No unapproved work or smoking in enclosed common areas.\n• Demo rules only; confirm the signed lease, parking assignment, and actual accessibility.' WHERE id=2 AND policies LIKE 'Quiet hours: 10:00 PM–7:00 AM. Register occupants and overnight guests%';
UPDATE apartments SET policies='• QUIET HOURS — Keep sound low 10:00 PM–7:00 AM.\n• HERITAGE FINISHES — No drilling, sanding, painting, or fixture changes without written consent.\n• OCCUPANTS — List residents in the lease; get permission for long-term guests.\n• PETS — Register approved pets and clean shared areas immediately.\n• SMOKING — No smoking/vaping in enclosed shared areas.\n• STAIRS & EXITS — Keep stair landings clear; confirm the accessible route before booking.\n• WATER & DRAINS — Do not flush wipes/grease; report leaks or slow drains quickly.\n• UTILITIES — Confirm meters or written allocation before signing.\n• WASTE — Use collection point; do not leave bags on stairs.\n• REPAIRS — Wait for owner authorization before permanent repair work.\n• WINDOWS — Do not pour water or shake rugs into neighboring spaces.\n• DELIVERIES — Coordinate large deliveries to protect narrow halls.\n• MOVE-IN — Photograph condition and record keys/fixtures.\n• Verify property-specific rules and accessibility with owner.' WHERE id=3 AND policies LIKE 'Please keep noise low after 10:00 PM, use the marked waste area%';
UPDATE apartments SET policies='• QUIET HOURS — Observe 10:00 PM–7:00 AM.\n• COURTYARD — Leave shared areas clean and supervise children.\n• OCCUPANTS/GUESTS — Name regular occupants and observe sign-in rules.\n• PETS — Prior written approval required.\n• PARKING — Get written stall assignment; do not block routes.\n• ACCESSIBILITY — Keep ramps, handrails, entries, and turning areas unobstructed.\n• FIRE SAFETY — Keep exits and extinguishers accessible.\n• WASTE — Use posted collection point and schedule.\n• UTILITIES — Review meter/allocation method, billing period, and due date.\n• MAINTENANCE — Report water, pest, light, and safety issues promptly.\n• SMOKING — No smoking/vaping in enclosed common areas.\n• ALTERATIONS — Written approval required for fixtures, locks, painting, or appliances.\n• MOVE-IN / OUT — Coordinate large items, protect common areas, return keys.\n• Confirm actual posted rules and lease terms; these are examples only.' WHERE id=4 AND policies LIKE 'Quiet hours run from 10:00 PM to 7:00 AM. Keep shared walkways%';
UPDATE apartments SET policies='• QUIET HOURS — Keep sound low 10:00 PM–7:00 AM.\n• OCCUPANCY — Only named residents; discuss long-stay guests in writing.\n• VISITORS — Follow security rules; do not share access.\n• PETS — Written approval required.\n• HISTORIC FABRIC — No drilling, painting, signs, or exterior alteration without written owner approval.\n• FIRE & ACCESS — Keep narrow corridors and stairs clear; confirm accessibility before booking.\n• WASTE — Seal rubbish and use designated collection point.\n• UTILITIES — Verify metering/allocation and due dates in the lease.\n• WATER/HUMIDITY — Report leaks promptly and protect historic materials.\n• DELIVERIES — Coordinate large deliveries to keep heritage paths open.\n• SMOKING — No smoking/vaping inside or in enclosed common areas.\n• PARKING — Not guaranteed unless assigned in writing.\n• MOVE-IN — Record condition and photos before placing furniture.\n• Confirm heritage/building restrictions and terms; demo rules only.' WHERE id=5 AND policies LIKE 'Respect heritage-building finishes and keep hallways%';
INSERT IGNORE INTO apartment_amenities(apartment_id,amenity) SELECT id,'parking' FROM apartments WHERE name IN ('Casa Pilar','Northline Residences','Rizal Park Lofts');
INSERT IGNORE INTO apartment_amenities(apartment_id,amenity) SELECT id,'elevator' FROM apartments WHERE name IN ('Northline Residences','The Linden House','Rizal Park Lofts');
INSERT IGNORE INTO apartment_amenities(apartment_id,amenity) SELECT id,'pwd_accessible' FROM apartments WHERE name='Mabini Court';
INSERT INTO apartments(name,area,address,description,policies,pet_friendly,image_url,featured) SELECT 'Coral Point Access Residences','Laiya Coast, San Juan, Batangas','Demo Seaside Road, Laiya, San Juan, Batangas','DEMO LISTING — A coastal apartment concept with marked parking, elevator service, step-free shared access, and nearby Laiya beach destinations. Confirm exact site, shoreline route, and accessibility before publication. Gallery photos are generic sample placeholders and must be replaced before publication.','• The property is a demo coastal example near Laiya shoreline attractions; verify exact beach access, opening hours, fees, tides, and travel time before booking. Shoreline access is not guaranteed by rent.\n• Observe 10:00 PM–7:00 AM quiet hours. Keep music and outdoor conversations low so nearby residents and guests can rest.\n• Rinse sand only at the designated outdoor wash point. Do not rinse sand into indoor sinks, toilets, drains, elevators, or corridors; dry wet floors immediately.\n• Only lease-listed occupants may reside in the unit. Register day visitors if property security requires it and respect posted visitor hours.\n• Pets require advance written approval, control on shared paths, and immediate waste cleanup. Keep animals away from restricted beach or pool areas.\n• Parking is available only in assigned marked spaces. Keep fire lanes, drop-off zones, accessible bays, ramps, and turning areas clear.\n• Observe posted elevator load limits and keep doors clear. Reserve the lift for move-ins; contain wet or sandy beach gear while transporting it.\n• Keep the step-free entrance, ramp, lift landing, handrails, and accessible path unobstructed. Confirm door widths, bathroom setup, and unit-specific accessibility before reservation.\n• Water and electricity use individual meters where provided or the written allocation method. Request itemized statements and retain receipts.\n• Seal food and beach waste, separate recyclables as posted, and never leave litter on coastal paths or in storm drains.\n• Follow official weather, coastal, and evacuation advisories. Management must provide current local emergency contacts at move-in.\n• Report water intrusion, corrosion, electrical issues, slippery floors, and damaged handrails promptly. Do not attempt electrical or structural repairs.\n• No smoking in enclosed shared spaces. Grills/open flames are allowed only in a designated location with owner permission.\n• Record condition, meter readings, parking assignment, keys, and access cards with management; coordinate bulky deliveries.\n• These are detailed demo guidelines, not an official rulebook. Verify the exact property, beach proximity, parking, lift, accessibility, utility billing, safety procedures, and lease with the owner before paying or signing.',0,'assets/feat-view.jpg',0 WHERE NOT EXISTS(SELECT 1 FROM apartments WHERE name='Coral Point Access Residences');
SET @coral=(SELECT id FROM apartments WHERE name='Coral Point Access Residences' ORDER BY id DESC LIMIT 1);
INSERT IGNORE INTO apartment_amenities(apartment_id,amenity) VALUES(@coral,'parking'),(@coral,'beach'),(@coral,'elevator'),(@coral,'pwd_accessible');
INSERT INTO units(apartment_id,floor_number,unit_number,unit_type,size_sqm,monthly_rent,image_url,features,status) SELECT @coral,1,'A1','1 Bedroom - Step-free access',38,22000,'assets/unit-1br.jpg','Parking, Elevator, Step-free common route, Wide entry approach, Near Laiya coast (demo location)','available' WHERE NOT EXISTS(SELECT 1 FROM units WHERE apartment_id=@coral AND unit_number='A1');
INSERT INTO units(apartment_id,floor_number,unit_number,unit_type,size_sqm,monthly_rent,image_url,features,status) SELECT @coral,2,'B2','1 Bedroom - Elevator access',43,28500,'assets/unit-1br.jpg','Parking, Elevator, Accessible common entrance, Coast nearby (demo location)','available' WHERE NOT EXISTS(SELECT 1 FROM units WHERE apartment_id=@coral AND unit_number='B2');
INSERT INTO units(apartment_id,floor_number,unit_number,unit_type,size_sqm,monthly_rent,image_url,features,status) SELECT @coral,3,'C3','2 Bedroom - Accessible route',62,38500,'assets/unit-2br.jpg','Parking, Elevator, Step-free common route, Two bedrooms, Coast nearby (demo location)','available' WHERE NOT EXISTS(SELECT 1 FROM units WHERE apartment_id=@coral AND unit_number='C3');
INSERT INTO unit_images(unit_id,image_path,caption,sort_order) SELECT u.id,imgs.image_path,imgs.caption,imgs.sort_order FROM units u JOIN (SELECT 'A1' unit_number UNION ALL SELECT 'B2' UNION ALL SELECT 'C3') wanted ON wanted.unit_number=u.unit_number JOIN apartments a ON a.id=u.apartment_id CROSS JOIN (SELECT 'assets/feat-kitchen.jpg' image_path,'Kitchen and dining' caption,1 sort_order UNION ALL SELECT 'assets/feat-bathroom.jpg','Bathroom',2 UNION ALL SELECT 'assets/feat-view.jpg','Generic sample photo — not a beach view',3 UNION ALL SELECT 'assets/feat-bedroom.jpg','Bedroom',4) imgs WHERE a.id=@coral AND NOT EXISTS(SELECT 1 FROM unit_images ui WHERE ui.unit_id=u.id AND ui.sort_order=imgs.sort_order);
